
const express = require("express");
const fs = require("fs");
const path = require("path");

const app = express();
const PORT = process.env.PORT || 3000;

const dataFile = path.join(__dirname, "profiles.json");

// Read form data
app.use(express.urlencoded({ extended: false }));

// Serve HTML and CSS files
app.use(express.static(__dirname));

// Make HTML safe before displaying user input
function escapeHTML(value) {
    return String(value).replace(/[&<>"']/g, function (char) {
        const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
        };
        return entities[char];
    });
}

// Create profile
app.post("/create-profile", (req, res) => {
    const name = String(req.body.name || "").trim();
    const bio = String(req.body.bio || "").trim();
    const skillsInput = String(req.body.skills || "").trim();
    const socialInput = String(req.body.social || "").trim();

    if (!name || !bio || !skillsInput) {
        return res.status(400).send("Please fill in all required fields.");
    }

    if (name.length > 100 || bio.length > 1000 || skillsInput.length > 500) {
        return res.status(400).send("Input is too long. Please try again.");
    }

    let social = "";

    if (socialInput) {
        try {
            const url = new URL(socialInput);

            if (!["http:", "https:"].includes(url.protocol)) {
                throw new Error("Invalid URL protocol");
            }

            social = url.href;
        } catch {
            return res.status(400).send("Please enter a valid social link.");
        }
    }

    const skills = skillsInput
        .split(",")
        .map(skill => skill.trim())
        .filter(Boolean)
        .slice(0, 20);

    // Read existing profiles
    let profiles = [];

    try {
        profiles = JSON.parse(fs.readFileSync(dataFile, "utf8"));

        if (!Array.isArray(profiles)) {
            throw new Error("Invalid profile data");
        }
    } catch (error) {
        console.error("Could not read profiles.json:", error.message);
        return res.status(500).send("Unable to read profile records.");
    }

    // Create a new profile record
    const profile = {
        id: Date.now().toString(),
        name,
        bio,
        skills,
        social,
        createdAt: new Date().toISOString()
    };

    profiles.push(profile);

    // Save profile in JSON file
    try {
        fs.writeFileSync(
            dataFile,
            JSON.stringify(profiles, null, 2),
            "utf8"
        );
    } catch (error) {
        console.error("Could not save profile:", error.message);
        return res.status(500).send("Unable to save your profile.");
    }

    const safeName = escapeHTML(profile.name);
    const safeBio = escapeHTML(profile.bio);

    const skillsHTML = profile.skills
        .map(skill => `<span class="skill">${escapeHTML(skill)}</span>`)
        .join(" ");

    const socialHTML = profile.social
        ? `<p><a href="${escapeHTML(profile.social)}" target="_blank" rel="noopener noreferrer">Visit Social Profile</a></p>`
        : "";

    const initial = escapeHTML(
        Array.from(profile.name)[0].toUpperCase()
    );

    // Return dynamically generated profile card
    res.send(`
        <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Your Profile Card</title>
            <link rel="stylesheet" href="/style.css">
        </head>
        <body>
            <header>
                <h1>Your Profile Card</h1>
                <p>Your profile was created successfully!</p>
            </header>

            <main>
                <section class="form-container profile-card">
                    <div class="avatar">${initial}</div>
                    <h2>${safeName}</h2>
                    <p>${safeBio}</p>

                    <h3>My Skills</h3>
                    <div class="skills">${skillsHTML}</div>

                    ${socialHTML}

                    <p><strong>Registration ID:</strong> ${profile.id}</p>

                    <a href="/" class="back-link">Create Another Profile</a>
                </section>
            </main>
        </body>
        </html>
    `);
});

// Start server
app.listen(PORT, () => {
    console.log(`Profile Card Generator running at http://localhost:${PORT}`);
});
